using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Object=UnityEngine.Object;
public static class FitRetailCaseBases {
 static Bounds LocalBounds(Transform model,Transform frame){bool first=true;var result=new Bounds();foreach(var f in model.GetComponentsInChildren<MeshFilter>(true)){var b=f.sharedMesh.bounds;var m=frame.worldToLocalMatrix*f.transform.localToWorldMatrix;for(int i=0;i<8;i++){var p=m.MultiplyPoint3x4(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(first){result=new Bounds(p,Vector3.zero);first=false;}else result.Encapsulate(p);}}if(first)throw new Exception("Missing mesh");return result;}
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Idle required");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();var root=d.transform.Find("DetailedMall_20261003");if(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Fitted retail case base"))throw new Exception("Already fitted");File.Copy(d.gameObject.scene.path,"outputs/chapter45-detailed-design-2026-10-03/scene-recovery/ShoeTower-before-case-fitting.unity",false);int count=0;foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="RetailCaseBase reused verified model")){var parent=t.parent;var before=LocalBounds(t,parent);var anchor=new Vector3(before.center.x,before.min.y,before.center.z);var wrapper=new GameObject("Fitted retail case base").transform;wrapper.SetParent(parent,false);wrapper.localPosition=anchor;t.SetParent(wrapper,true);var b=LocalBounds(t,wrapper);wrapper.localScale=new Vector3(2.3f/b.size.x,.8f/b.size.y,1.8f/b.size.z);var after=LocalBounds(t,parent);if(Vector3.Distance(after.size,new Vector3(2.3f,.8f,1.8f))>.01f)throw new Exception("Case dimensions invalid");count++;}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);return new{fitted=count,displayDimensions=new[]{2.3f,.8f,1.8f},reason="Original low cabinet-base crop is very wide when normalized by height; fit its existing generated mesh into authored glazing footprint with a parent wrapper, preserving imported child axes",sourceMeshModified=false,addedColliders=0};}
}
